import React from "react"
import { FaArrowRight } from "react-icons/fa6"
import { content } from "../client-data/una-tile/content"
import { Reveal } from "./Reveal"

export const Services = ({ onQuote }: { onQuote: (service?: string) => void }) => {
    const { services } = content
    return (
        <section className="section section--soft" id="services" aria-labelledby="services-title">
            <div className="container">
                <Reveal className="section-head section-head--center">
                    <span className="eyebrow">{services.eyebrow}</span>
                    <h2 id="services-title">{services.title}</h2>
                    <p>{services.subtitle}</p>
                </Reveal>

                <div className="services">
                    {services.items.map((s, i) => (
                        <Reveal key={s.id} as="article" delay={i * 110} className="service">
                            <div className="service__img">
                                <img src={s.img} alt={s.alt} loading="lazy" decoding="async" width={1020} height={765} />
                            </div>
                            <div className="service__body">
                                <h3>{s.title}</h3>
                                {s.paragraphs.map(p => (
                                    <p key={p}>{p}</p>
                                ))}
                                <button type="button" className="service__link" onClick={() => onQuote(s.title)}>
                                    Get a {s.title.toLowerCase()} estimate
                                    <FaArrowRight aria-hidden="true" />
                                </button>
                            </div>
                        </Reveal>
                    ))}
                </div>
            </div>
        </section>
    )
}
