import React from "react"
import { FaCircleCheck } from "react-icons/fa6"
import { company, content } from "../client-data/una-tile/content"
import { Reveal } from "./Reveal"

export const About = ({ onQuote }: { onQuote: () => void }) => {
    const { about } = content
    return (
        <section className="section" id="about" aria-labelledby="about-title">
            <div className="container about">
                <Reveal className="about__media">
                    <img className="about__img" src={about.img} alt={about.alt} loading="lazy" decoding="async" width={2000} height={1271} />
                    <div className="about__badge">
                        <strong>{about.badge.value}</strong>
                        <span>{about.badge.label}</span>
                    </div>
                </Reveal>

                <Reveal delay={120}>
                    <span className="eyebrow">{about.eyebrow}</span>
                    <h2 id="about-title">{about.title}</h2>
                    <div className="about__text">
                        {about.paragraphs.map(p => (
                            <p key={p}>{p}</p>
                        ))}
                    </div>
                    <ul className="about__list">
                        {about.checks.map(c => (
                            <li key={c}>
                                <FaCircleCheck aria-hidden="true" />
                                {c}
                            </li>
                        ))}
                    </ul>
                    <div className="about__actions">
                        <button type="button" className="btn" onClick={onQuote}>
                            Request a Quote
                        </button>
                        <a className="btn btn--outline" href={`tel:${company.phone.tel}`}>
                            Call {company.phone.display}
                        </a>
                    </div>
                </Reveal>
            </div>
        </section>
    )
}
