import React from "react"
import { FaGoogle, FaPenToSquare, FaStar } from "react-icons/fa6"
import { company, content } from "../client-data/una-tile/content"
import { Reveal } from "./Reveal"

const HONORIFICS = /^(mr|mrs|ms|miss|dr)\.?$/i

const initials = (name: string) => {
    const words = name.split(/\s+/).filter(w => w && !HONORIFICS.test(w))
    if (words.length === 0) return name.slice(0, 1).toUpperCase()
    const first = words[0][0]
    const last = words.length > 1 ? words[words.length - 1][0] : ""
    return (first + last).toUpperCase()
}

export const Reviews = () => {
    const { reviews } = content
    return (
        <section className="section section--soft" id="reviews" aria-labelledby="reviews-title">
            <div className="container">
                <div className="reviews__head">
                    <Reveal className="section-head">
                        <span className="eyebrow">{reviews.eyebrow}</span>
                        <h2 id="reviews-title">{reviews.title}</h2>
                        <p>{reviews.subtitle}</p>
                    </Reveal>
                    <Reveal className="reviews__actions" delay={100}>
                        <a className="btn btn--outline btn--sm" href={company.google.profile} target="_blank" rel="noopener noreferrer">
                            <FaGoogle aria-hidden="true" />
                            See all reviews
                        </a>
                        <a className="btn btn--sm" href={company.google.writeReview} target="_blank" rel="noopener noreferrer">
                            <FaPenToSquare aria-hidden="true" />
                            Leave a review
                        </a>
                    </Reveal>
                </div>

                <div className="reviews">
                    {reviews.items.map((r, i) => (
                        <Reveal key={r.name} as="figure" delay={(i % 3) * 90} className="review">
                            <div className="review__stars" role="img" aria-label="5 out of 5 stars">
                                {[0, 1, 2, 3, 4].map(n => (
                                    <FaStar key={n} aria-hidden="true" />
                                ))}
                            </div>
                            <blockquote>“{r.text}”</blockquote>
                            <figcaption>
                                <span className="review__avatar" aria-hidden="true">
                                    {initials(r.name)}
                                </span>
                                <span>
                                    <span className="review__name">{r.name}</span>
                                    <span className="review__meta">{r.when} · Google review</span>
                                </span>
                                <FaGoogle className="review__g" aria-hidden="true" style={{ color: "#4285f4" }} />
                            </figcaption>
                        </Reveal>
                    ))}
                </div>
            </div>
        </section>
    )
}
