import React, { useCallback, useEffect, useRef, useState } from "react"
import { FaChevronLeft, FaChevronRight, FaMagnifyingGlassPlus, FaXmark } from "react-icons/fa6"
import { content, gallery } from "../client-data/una-tile/content"
import { Reveal } from "./Reveal"

export const Gallery = () => {
    const [active, setActive] = useState<number | null>(null)
    const info = content.gallery

    return (
        <section className="section" id="gallery" aria-labelledby="gallery-title">
            <div className="container">
                <Reveal className="section-head section-head--center">
                    <span className="eyebrow">{info.eyebrow}</span>
                    <h2 id="gallery-title">{info.title}</h2>
                    <p>{info.subtitle}</p>
                </Reveal>

                <div className="gallery">
                    {gallery.map((img, i) => (
                        <button
                            key={img.url}
                            type="button"
                            className={`gallery__item${img.wide ? " gallery__item--wide" : ""}`}
                            onClick={() => setActive(i)}
                            aria-label={`Open photo ${i + 1} of ${gallery.length}: ${img.alt}`}
                        >
                            <img src={img.url} alt="" width={img.w} height={img.h} loading="lazy" decoding="async" />
                            <span className="gallery__zoom" aria-hidden="true">
                                <FaMagnifyingGlassPlus />
                            </span>
                        </button>
                    ))}
                </div>
            </div>

            <Lightbox index={active} onChange={setActive} />
        </section>
    )
}

/** Full-screen photo viewer built on the native <dialog> (focus trap + Esc for free). */
const Lightbox = ({ index, onChange }: { index: number | null; onChange: (i: number | null) => void }) => {
    const ref = useRef<HTMLDialogElement>(null)
    const touchX = useRef<number | null>(null)
    const open = index !== null

    useEffect(() => {
        const dlg = ref.current
        if (!dlg) return
        if (open && !dlg.open) dlg.showModal()
        if (!open && dlg.open) dlg.close()
    }, [open])

    useEffect(() => {
        if (!open) return
        const prev = document.body.style.overflow
        document.body.style.overflow = "hidden"
        return () => {
            document.body.style.overflow = prev
        }
    }, [open])

    const go = useCallback(
        (step: number) => {
            if (index === null) return
            onChange((index + step + gallery.length) % gallery.length)
        },
        [index, onChange]
    )

    // Warm the next photo so arrow-through feels instant.
    useEffect(() => {
        if (index === null) return
        const next = new Image()
        next.src = gallery[(index + 1) % gallery.length].url
    }, [index])

    const onKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === "ArrowRight") go(1)
        if (e.key === "ArrowLeft") go(-1)
    }

    const img = index !== null ? gallery[index] : null

    return (
        <dialog
            ref={ref}
            className="lightbox"
            aria-label="Photo viewer"
            onClose={() => onChange(null)}
            onKeyDown={onKeyDown}
            onClick={e => {
                // A click on the dialog itself (not its children) is a click on the backdrop.
                if (e.target === e.currentTarget) onChange(null)
            }}
            onTouchStart={e => (touchX.current = e.touches[0].clientX)}
            onTouchEnd={e => {
                if (touchX.current === null) return
                const dx = e.changedTouches[0].clientX - touchX.current
                touchX.current = null
                if (Math.abs(dx) > 50) go(dx < 0 ? 1 : -1)
            }}
        >
            {img && (
                <>
                    <img className="lightbox__img" src={img.url} alt={img.alt} />
                    <button type="button" className="icon-btn" aria-label="Close photo viewer" onClick={() => onChange(null)}>
                        <FaXmark aria-hidden="true" />
                    </button>
                    <button type="button" className="lightbox__nav lightbox__nav--prev" aria-label="Previous photo" onClick={() => go(-1)}>
                        <FaChevronLeft aria-hidden="true" />
                    </button>
                    <button type="button" className="lightbox__nav lightbox__nav--next" aria-label="Next photo" onClick={() => go(1)}>
                        <FaChevronRight aria-hidden="true" />
                    </button>
                    <span className="lightbox__count" aria-live="polite">
                        {index! + 1} / {gallery.length}
                    </span>
                </>
            )}
        </dialog>
    )
}
