import React, { useEffect, useState } from "react"
import { FaBars, FaEnvelope, FaFacebookF, FaInstagram, FaPhone, FaXmark } from "react-icons/fa6"
import logo from "../client-data/una-tile/local-assets/una-tile-logo-text-and-image.svg"
import { company, content } from "../client-data/una-tile/content"

export const Header = ({ onQuote }: { onQuote: () => void }) => {
    const [scrolled, setScrolled] = useState(false)
    const [open, setOpen] = useState(false)
    const [active, setActive] = useState("")

    useEffect(() => {
        const onScroll = () => setScrolled(window.scrollY > 8)
        onScroll()
        window.addEventListener("scroll", onScroll, { passive: true })
        return () => window.removeEventListener("scroll", onScroll)
    }, [])

    // Highlight the nav link for the section currently in view.
    useEffect(() => {
        if (typeof IntersectionObserver === "undefined") return
        const targets = content.nav
            .map(n => document.getElementById(n.id))
            .filter((el): el is HTMLElement => !!el)
        const io = new IntersectionObserver(
            entries => {
                const hit = entries.filter(e => e.isIntersecting).sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0]
                if (hit) setActive(hit.target.id)
            },
            { rootMargin: "-35% 0px -55% 0px", threshold: [0, 0.2, 0.5] }
        )
        targets.forEach(t => io.observe(t))
        return () => io.disconnect()
    }, [])

    // Drawer: lock page scroll and close on Escape.
    useEffect(() => {
        if (!open) return
        const prev = document.body.style.overflow
        document.body.style.overflow = "hidden"
        const onKey = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false)
        window.addEventListener("keydown", onKey)
        return () => {
            document.body.style.overflow = prev
            window.removeEventListener("keydown", onKey)
        }
    }, [open])

    const close = () => setOpen(false)

    return (
        <header className={`site-header${scrolled ? " is-scrolled" : ""}`}>
            <div className="topbar">
                <div className="container topbar__inner">
                    <div className="topbar__left">
                        <a className="topbar__phone" href={`tel:${company.phone.tel}`}>
                            <FaPhone aria-hidden="true" />
                            {company.phone.display}
                        </a>
                        <a className="topbar__email" href={`mailto:${company.email}`}>
                            <FaEnvelope aria-hidden="true" />
                            {company.email}
                        </a>
                    </div>
                    <div className="topbar__right">
                        <span>Serving {company.serviceAreas.join(" · ")}</span>
                        <span className="topbar__right topbar__social">
                            <a href={company.social.facebook} target="_blank" rel="noopener noreferrer" aria-label="Una Tile on Facebook">
                                <FaFacebookF aria-hidden="true" />
                            </a>
                            <a href={company.social.instagram} target="_blank" rel="noopener noreferrer" aria-label="Una Tile on Instagram">
                                <FaInstagram aria-hidden="true" />
                            </a>
                        </span>
                    </div>
                </div>
            </div>

            <div className="container navbar">
                <a className="brand" href="#top" aria-label="Una Tile — back to top">
                    <img src={logo} alt="Una Tile" width={201} height={44} />
                </a>

                <nav className="nav" aria-label="Primary">
                    {content.nav.map(n => (
                        <a key={n.id} href={`#${n.id}`} className={active === n.id ? "is-active" : ""} aria-current={active === n.id ? "true" : undefined}>
                            {n.label}
                        </a>
                    ))}
                </nav>

                <div className="navbar__cta">
                    <a className="btn btn--outline btn--sm" href={`tel:${company.phone.tel}`}>
                        <FaPhone aria-hidden="true" />
                        {company.phone.display}
                    </a>
                    <button type="button" className="btn btn--primary btn--sm" onClick={onQuote}>
                        Free Estimate
                    </button>
                    <button
                        type="button"
                        className="menu-toggle"
                        aria-label="Open menu"
                        aria-expanded={open}
                        aria-controls="mobile-menu"
                        onClick={() => setOpen(true)}
                    >
                        <FaBars aria-hidden="true" />
                    </button>
                </div>
            </div>

            <div id="mobile-menu" className={`drawer${open ? " is-open" : ""}`} aria-hidden={!open}>
                <div className="drawer__scrim" onClick={close} />
                <div className="drawer__panel" role="dialog" aria-modal="true" aria-label="Menu">
                    <div className="drawer__head">
                        <img src={logo} alt="Una Tile" width={174} height={38} />
                        <button type="button" className="menu-toggle" aria-label="Close menu" onClick={close}>
                            <FaXmark aria-hidden="true" />
                        </button>
                    </div>
                    {content.nav.map(n => (
                        <a key={n.id} className="drawer__link" href={`#${n.id}`} onClick={close}>
                            {n.label}
                        </a>
                    ))}
                    <div className="drawer__cta">
                        <a className="btn btn--outline" href={`tel:${company.phone.tel}`}>
                            <FaPhone aria-hidden="true" />
                            Call {company.phone.display}
                        </a>
                        <button
                            type="button"
                            className="btn btn--primary"
                            onClick={() => {
                                close()
                                onQuote()
                            }}
                        >
                            Get a Free Estimate
                        </button>
                    </div>
                    <p className="drawer__meta">
                        {company.address.full}
                        <br />
                        <a href={`mailto:${company.email}`}>{company.email}</a>
                    </p>
                </div>
            </div>
        </header>
    )
}
