import { company } from "../client-data/una-tile/content"

export type LeadRequest = {
    name: string
    phone: string
    email: string
    service: string
    message: string
}

export type LeadResult = { ok: true; via: "mailto" } | { ok: false; error: string }

/**
 * The single place quote requests leave the site.
 *
 * Right now this opens the visitor's email app with a pre-filled message to
 * the business, because the site has no backend or form service attached.
 * To switch to a real endpoint, replace the body of this function with a
 * fetch() to that endpoint and return { ok: true, via: ... } — nothing else
 * in the UI needs to change.
 */
export const submitLead = async (lead: LeadRequest): Promise<LeadResult> => {
    const lines = [
        `Name: ${lead.name}`,
        `Phone: ${lead.phone || "-"}`,
        `Email: ${lead.email || "-"}`,
        `Service: ${lead.service || "-"}`,
        "",
        lead.message || "(no message)",
    ]
    const subject = `Estimate request from ${lead.name}`
    const href = `mailto:${company.email}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(lines.join("\n"))}`
    try {
        window.location.href = href
        return { ok: true, via: "mailto" }
    } catch (e) {
        return { ok: false, error: "Could not open your email app." }
    }
}
