import React, { useEffect, useRef, useState } from "react"

type State = "visible" | "pending"

/**
 * Fades content up as it scrolls into view.
 *
 * Server render + first paint are always "visible", so content is never hidden
 * for crawlers, no-JS visitors or reduced-motion users. Only elements that are
 * below the fold when the page hydrates are switched to "pending" and revealed
 * once they intersect.
 */
export const Reveal = ({
    children,
    delay = 0,
    className = "",
    as = "div",
}: {
    children: React.ReactNode
    delay?: number
    className?: string
    as?: React.ElementType
}) => {
    const ref = useRef<HTMLElement | null>(null)
    const [state, setState] = useState<State>("visible")

    useEffect(() => {
        const el = ref.current
        if (!el) return
        const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
        if (reduced || typeof IntersectionObserver === "undefined") return
        if (el.getBoundingClientRect().top < window.innerHeight) return

        setState("pending")
        const io = new IntersectionObserver(
            entries => {
                if (entries.some(e => e.isIntersecting)) {
                    setState("visible")
                    io.disconnect()
                }
            },
            { rootMargin: "0px 0px -8% 0px" }
        )
        io.observe(el)
        return () => io.disconnect()
    }, [])

    const Tag = as
    return (
        <Tag
            ref={ref}
            className={`reveal is-${state} ${className}`.trim()}
            style={delay ? ({ "--d": `${delay}ms` } as React.CSSProperties) : undefined}
        >
            {children}
        </Tag>
    )
}
