import React from "react"
import { FaAward, FaBolt, FaGem, FaHouse, FaMagnifyingGlass, FaShieldHalved } from "react-icons/fa6"
import { content } from "../client-data/una-tile/content"
import { Reveal } from "./Reveal"

const icons: Record<string, React.ElementType> = {
    shield: FaShieldHalved,
    award: FaAward,
    gem: FaGem,
    home: FaHouse,
    bolt: FaBolt,
    detail: FaMagnifyingGlass,
}

export const Features = () => {
    const { features } = content
    return (
        <section className="section" id="why-us" aria-labelledby="why-title">
            <div className="container">
                <Reveal className="section-head section-head--center">
                    <span className="eyebrow">{features.eyebrow}</span>
                    <h2 id="why-title">{features.title}</h2>
                    <p>{features.subtitle}</p>
                </Reveal>

                <div className="features">
                    {features.items.map((item, i) => {
                        const Icon = icons[item.icon] ?? FaGem
                        return (
                            <Reveal key={item.title} delay={(i % 3) * 90} className="feature">
                                <div className="feature__icon">
                                    <Icon aria-hidden="true" />
                                </div>
                                <h3>{item.title}</h3>
                                <p>{item.text}</p>
                            </Reveal>
                        )
                    })}
                </div>
            </div>
        </section>
    )
}
