import React, { useEffect, useRef, useState } from "react"
import { FaCircleCheck, FaPhone, FaXmark } from "react-icons/fa6"
import { company, content } from "../client-data/una-tile/content"
import { submitLead } from "./lead"

type Values = { name: string; phone: string; email: string; service: string; message: string }
type Errors = Partial<Record<keyof Values, string>>

const EMPTY: Values = { name: "", phone: "", email: "", service: "", message: "" }

const validate = (v: Values): Errors => {
    const errors: Errors = {}
    if (!v.name.trim()) errors.name = "Please tell us your name."
    const digits = v.phone.replace(/\D/g, "")
    if (!v.phone.trim() && !v.email.trim()) {
        errors.phone = "Add a phone number or an email so we can reach you."
    } else {
        if (v.phone.trim() && digits.length < 10) errors.phone = "That phone number looks too short."
        if (v.email.trim() && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.email.trim())) errors.email = "That email address doesn't look right."
    }
    return errors
}

export const QuoteDialog = ({ open, service, onClose }: { open: boolean; service?: string; onClose: () => void }) => {
    const ref = useRef<HTMLDialogElement>(null)
    const [values, setValues] = useState<Values>(EMPTY)
    const [errors, setErrors] = useState<Errors>({})
    const [sent, setSent] = useState(false)
    const [sending, setSending] = useState(false)
    const [failure, setFailure] = useState("")

    useEffect(() => {
        const dlg = ref.current
        if (!dlg) return
        if (open && !dlg.open) {
            setValues({ ...EMPTY, service: service ?? "" })
            setErrors({})
            setSent(false)
            setFailure("")
            dlg.showModal()
        }
        if (!open && dlg.open) dlg.close()
    }, [open, service])

    useEffect(() => {
        if (!open) return
        const prev = document.body.style.overflow
        document.body.style.overflow = "hidden"
        return () => {
            document.body.style.overflow = prev
        }
    }, [open])

    const set = (key: keyof Values) => (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        setValues(v => ({ ...v, [key]: e.target.value }))
        if (errors[key]) setErrors(er => ({ ...er, [key]: undefined }))
    }

    const onSubmit = async (e: React.FormEvent) => {
        e.preventDefault()
        const found = validate(values)
        setErrors(found)
        if (Object.keys(found).length) {
            const first = Object.keys(found)[0]
            ref.current?.querySelector<HTMLElement>(`[name="${first}"]`)?.focus()
            return
        }
        setSending(true)
        setFailure("")
        const result = await submitLead(values)
        setSending(false)
        if (result.ok) setSent(true)
        else setFailure(`${result.error} Please call us at ${company.phone.display}.`)
    }

    const { quote } = content

    return (
        <dialog
            ref={ref}
            className="quote"
            aria-labelledby="quote-title"
            onClose={onClose}
            onClick={e => {
                if (e.target === e.currentTarget) onClose()
            }}
        >
            <div className="quote__head">
                <h2 id="quote-title">{quote.title}</h2>
                <p>{quote.subtitle}</p>
                <button type="button" className="icon-btn" aria-label="Close" onClick={onClose}>
                    <FaXmark aria-hidden="true" />
                </button>
            </div>

            {sent ? (
                <div className="quote__done" role="status">
                    <FaCircleCheck aria-hidden="true" />
                    <h3>Your email is ready to send</h3>
                    <p>
                        We've opened your email app with your request filled in — just press send. Prefer to talk it through? Call us at{" "}
                        <a href={`tel:${company.phone.tel}`}>
                            <strong>{company.phone.display}</strong>
                        </a>
                        .
                    </p>
                    <button type="button" className="btn" onClick={onClose}>
                        Done
                    </button>
                </div>
            ) : (
                <form className="quote__form" onSubmit={onSubmit} noValidate>
                    <div className="field">
                        <label htmlFor="q-name">Your name</label>
                        <input
                            id="q-name"
                            name="name"
                            type="text"
                            autoComplete="name"
                            autoFocus
                            value={values.name}
                            onChange={set("name")}
                            aria-invalid={!!errors.name}
                            aria-describedby={errors.name ? "q-name-err" : undefined}
                        />
                        {errors.name && (
                            <span id="q-name-err" className="field__error">
                                {errors.name}
                            </span>
                        )}
                    </div>

                    <div className="field__row">
                        <div className="field">
                            <label htmlFor="q-phone">Phone</label>
                            <input
                                id="q-phone"
                                name="phone"
                                type="tel"
                                inputMode="tel"
                                autoComplete="tel"
                                value={values.phone}
                                onChange={set("phone")}
                                aria-invalid={!!errors.phone}
                                aria-describedby={errors.phone ? "q-phone-err" : undefined}
                            />
                            {errors.phone && (
                                <span id="q-phone-err" className="field__error">
                                    {errors.phone}
                                </span>
                            )}
                        </div>
                        <div className="field">
                            <label htmlFor="q-email">Email</label>
                            <input
                                id="q-email"
                                name="email"
                                type="email"
                                inputMode="email"
                                autoComplete="email"
                                value={values.email}
                                onChange={set("email")}
                                aria-invalid={!!errors.email}
                                aria-describedby={errors.email ? "q-email-err" : undefined}
                            />
                            {errors.email && (
                                <span id="q-email-err" className="field__error">
                                    {errors.email}
                                </span>
                            )}
                        </div>
                    </div>

                    <div className="field">
                        <label htmlFor="q-service">What do you need?</label>
                        <select id="q-service" name="service" value={values.service} onChange={set("service")}>
                            <option value="">Select a service</option>
                            {quote.services.map(s => (
                                <option key={s} value={s}>
                                    {s}
                                </option>
                            ))}
                        </select>
                    </div>

                    <div className="field">
                        <label htmlFor="q-message">
                            Tell us about your project <span>(optional)</span>
                        </label>
                        <textarea id="q-message" name="message" value={values.message} onChange={set("message")} />
                    </div>

                    {failure && (
                        <p className="field__error" role="alert">
                            {failure}
                        </p>
                    )}

                    <button type="submit" className="btn btn--primary btn--block" disabled={sending}>
                        {sending ? "Opening your email…" : "Send my request"}
                    </button>
                    <p className="quote__note">
                        Or call <a href={`tel:${company.phone.tel}`}>{company.phone.display}</a>
                        <FaPhone aria-hidden="true" style={{ display: "inline", width: 12, height: 12, marginLeft: 6, verticalAlign: "-1px" }} />
                    </p>
                </form>
            )}
        </dialog>
    )
}
