import React from "react"
import { motion } from "framer-motion"
import UnaTileLogoTop from "../client-data/una-tile/local-assets/una-tile-logo-top.svg"
import UnaTileLogoBottom from "../client-data/una-tile/local-assets/una-tile-logo-bottom.svg"
import UnaTileLogoText from "../client-data/una-tile/local-assets/una-tile-logo-text.svg"

/**
 * The intro loading animation — same assets and timings as the original
 * site: the two halves of the logo slide together, spin once, the wordmark
 * fades in, then the whole screen fades away.
 *
 * The halves slide with `y`, not margins, so the spinning box is exactly the
 * size of the logo. Its centre is the pivot: any extra space in that box
 * would make the logo orbit instead of spinning on the spot.
 */
export const LoadingIntro = ({ hide }: { hide?: boolean }) => {
    if (hide) return <></>
    return (
        <motion.div
            aria-hidden="true"
            className="intro-guard"
            initial={{ display: "block" }}
            animate={{ display: "none" }}
            transition={{ delay: 4.5, duration: 0.1 }}
        >
            <motion.div
                initial={{ opacity: 1, position: "fixed", top: 0, left: 0, width: "100vw", height: "100vh", zIndex: 9999 }}
                animate={{ opacity: 0, height: 0 }}
                transition={{ delay: 3.5, duration: 1.0 }}
            >
                <div style={{ backgroundColor: "white", width: "100vw", height: "100vh" }}>
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        transition={{ delay: 0.5, duration: 0.5 }}
                    >
                        <div
                            style={{
                                height: "100vh",
                                display: "flex",
                                flexDirection: "column",
                                alignItems: "center",
                                justifyContent: "center",
                            }}
                        >
                            <motion.div
                                style={{ transformOrigin: "center center" }}
                                initial={{ transform: "rotate(0deg)" }}
                                animate={{ transform: "rotate(360deg)" }}
                                transition={{ delay: 1.5, duration: 0.4 }}
                            >
                                <motion.div
                                    initial={{ y: "-100vh" }}
                                    animate={{ y: 0 }}
                                    transition={{ delay: 1, duration: 0.5 }}
                                >
                                    <img src={UnaTileLogoTop} alt="" width={143} height={96} />
                                </motion.div>
                                <motion.div
                                    style={{ marginTop: "-50px" }}
                                    initial={{ y: "100vh" }}
                                    animate={{ y: 0 }}
                                    transition={{ delay: 1, duration: 0.5 }}
                                >
                                    <img src={UnaTileLogoBottom} alt="" width={143} height={95} />
                                </motion.div>
                            </motion.div>
                            <div style={{ height: 10 }} />
                            <motion.div
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                transition={{ delay: 2.5, duration: 0.5 }}
                            >
                                <img src={UnaTileLogoText} alt="Una Tile" />
                            </motion.div>
                        </div>
                    </motion.div>
                </div>
            </motion.div>
        </motion.div>
    )
}
