import React, { useEffect, useRef, useState } from "react"
import { FaCheck, FaPhone } from "react-icons/fa6"
import { company, content } from "../client-data/una-tile/content"

const SLIDE_MS = 6000

export const Hero = ({ onQuote }: { onQuote: () => void }) => {
    const { hero } = content
    const [index, setIndex] = useState(0)
    // Only the first photo is needed to paint the page; fetch the rest a moment later.
    const [loadAll, setLoadAll] = useState(false)
    const slides = useRef<HTMLDivElement>(null)

    useEffect(() => {
        const id = window.setTimeout(() => setLoadAll(true), 2500)
        return () => window.clearTimeout(id)
    }, [])

    // Auto-advance, but not for reduced-motion users and not while the tab is hidden.
    useEffect(() => {
        const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
        if (reduced || hero.images.length < 2) return
        const id = window.setInterval(() => {
            if (!document.hidden) setIndex(i => (i + 1) % hero.images.length)
        }, SLIDE_MS)
        return () => window.clearInterval(id)
    }, [hero.images.length])

    // Every photo's zoom keeps running, so a slide fading out never jumps.
    // A photo only restarts from the beginning while it is still hidden.
    useEffect(() => {
        const slide = slides.current?.querySelector(".is-active")
        if (!slide || Number(getComputedStyle(slide).opacity) > 0.1) return
        slide.querySelector("img")?.getAnimations().forEach(a => {
            a.currentTime = 0
        })
    }, [index])

    return (
        <section className="hero" id="top" aria-labelledby="hero-title">
            <div className="hero__slides" ref={slides} aria-hidden="true">
                {hero.images.map((img, i) =>
                    i === 0 || loadAll || i === index ? (
                        <div key={img.url} className={`hero__slide${i === index ? " is-active" : ""}`}>
                            <img
                                src={img.url}
                                alt=""
                                // First slide is the largest paint on the page: load it eagerly and early.
                                loading={i === 0 ? "eager" : "lazy"}
                                {...(i === 0 ? ({ fetchpriority: "high" } as Record<string, string>) : {})}
                                decoding="async"
                            />
                        </div>
                    ) : null
                )}
            </div>

            <div className="container">
                <div className="hero__content">
                    <span className="eyebrow">{hero.eyebrow}</span>
                    <h1 id="hero-title">{hero.title}</h1>
                    <p className="hero__sub">{hero.subtitle}</p>

                    <div className="hero__actions">
                        <button type="button" className="btn btn--primary" onClick={onQuote}>
                            {hero.cta}
                        </button>
                        <a className="btn btn--light" href={`tel:${company.phone.tel}`}>
                            <FaPhone aria-hidden="true" />
                            {company.phone.display}
                        </a>
                    </div>

                    <ul className="hero__trust">
                        {hero.trust.map(t => (
                            <li key={t}>
                                <FaCheck aria-hidden="true" />
                                {t}
                            </li>
                        ))}
                    </ul>
                </div>
            </div>

            {hero.images.length > 1 && (
                <div className="hero__dots">
                    {hero.images.map((_, i) => (
                        <button
                            key={i}
                            type="button"
                            aria-label={`Show photo ${i + 1} of ${hero.images.length}`}
                            aria-current={i === index}
                            onClick={() => setIndex(i)}
                        />
                    ))}
                </div>
            )}
        </section>
    )
}
