import React, { useCallback, useState } from "react"
import type { HeadFC } from "gatsby"
import { company, content } from "../client-data/una-tile/content"
import { Header } from "../site/Header"
import { Hero } from "../site/Hero"
import { Features } from "../site/Features"
import { Services } from "../site/Services"
import { Gallery } from "../site/Gallery"
import { About } from "../site/About"
import { Reviews } from "../site/Reviews"
import { Contact } from "../site/Contact"
import { Footer } from "../site/Footer"
import { CallBar } from "../site/CallBar"
import { QuoteDialog } from "../site/QuoteDialog"
import { LoadingIntro } from "../site/LoadingIntro"

export default function IndexPage() {
    const [quoteOpen, setQuoteOpen] = useState(false)
    const [quoteService, setQuoteService] = useState<string | undefined>()

    const openQuote = useCallback((service?: string) => {
        setQuoteService(service)
        setQuoteOpen(true)
    }, [])

    return (
        <>
            <a className="skip-link" href="#main">
                Skip to content
            </a>

            <Header onQuote={() => openQuote()} />

            <main id="main">
                <Hero onQuote={() => openQuote()} />
                <Features />
                <Services onQuote={openQuote} />
                <Gallery />
                <About onQuote={() => openQuote()} />
                <Reviews />
                <Contact onQuote={() => openQuote()} />
            </main>

            <Footer />
            <CallBar onQuote={() => openQuote()} />
            <QuoteDialog open={quoteOpen} service={quoteService} onClose={() => setQuoteOpen(false)} />

            {/* The intro animation from the original site — kept as requested. */}
            <LoadingIntro />
        </>
    )
}

const structuredData = {
    "@context": "https://schema.org",
    "@type": "HomeAndConstructionBusiness",
    name: company.name,
    legalName: company.legalName,
    url: `${company.url}/`,
    image: `${company.url}/og.jpg`,
    description: content.page.description,
    telephone: company.phone.tel,
    email: company.email,
    address: {
        "@type": "PostalAddress",
        streetAddress: company.address.street,
        addressLocality: company.address.city,
        addressRegion: company.address.region,
        postalCode: company.address.zip,
        addressCountry: "US",
    },
    areaServed: company.serviceAreas.map(name => ({ "@type": "City", name })),
}

export const Head: HeadFC = () => (
    <>
        <html lang="en" />
        <title>{content.page.title}</title>
        <meta name="description" content={content.page.description} />
        <meta name="theme-color" content="#002F5D" />
        <link rel="canonical" href={`${company.url}/`} />
        {/* The first hero photo is the largest thing painted: fetch it as early as possible. */}
        <link rel="preload" as="image" href={content.hero.images[0].url} {...({ fetchpriority: "high" } as Record<string, string>)} />

        <meta property="og:type" content="website" />
        <meta property="og:site_name" content={company.name} />
        <meta property="og:title" content={content.page.title} />
        <meta property="og:description" content={content.page.description} />
        <meta property="og:url" content={`${company.url}/`} />
        <meta property="og:image" content={`${company.url}/og.jpg`} />
        <meta name="twitter:card" content="summary_large_image" />

        <script type="application/ld+json">{JSON.stringify(structuredData)}</script>
    </>
)
